using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace AuroraProxy {
 public partial class MainForm {
  readonly ToolTip hints=new ToolTip(){AutoPopDelay=12000,InitialDelay=500,ReshowDelay=100};
  readonly Dictionary<SoftButton,Func<bool>> availability=new Dictionary<SoftButton,Func<bool>>();
  bool noticeError,pendingGlobal,pendingConnect,restoreNodeView,focusNodeSearch;string pendingProfile,rememberedProfile,rememberedGroup,rememberedSearch;
  ViewBookmark nodeBookmark,profileBookmark;Label nodeHint;
  class ViewBookmark {
   public string Selected,Focused,Top;public int TopIndex,SelectedIndex;
   public static string Key(ListViewItem item){var profile=item.Tag as Subscription;return profile==null?item.Tag as string:profile.Id;}
   public static ViewBookmark Capture(ListView list){if(list==null||list.IsDisposed)return null;var top=list.Items.Count==0?null:list.TopItem;return new ViewBookmark(){SelectedIndex=list.SelectedItems.Count==0?0:list.SelectedItems[0].Index,Selected=list.SelectedItems.Count==0?null:Key(list.SelectedItems[0]),Focused=list.FocusedItem==null?null:Key(list.FocusedItem),Top=top==null?null:Key(top),TopIndex=top==null?0:top.Index};}
   public void Restore(ListView list,string selected=null){foreach(ListViewItem item in list.Items){item.Selected=Key(item)==(selected??Selected);if(Key(item)==Focused)item.Focused=true;}if(list.Items.Count>0&&Top!=null){var top=list.Items.Cast<ListViewItem>().FirstOrDefault(x=>Key(x)==Top);list.TopItem=top??list.Items[Math.Min(TopIndex,list.Items.Count-1)];}}
  }
  void RestoreAfterLayout(ListView list,ViewBookmark bookmark,string selected,bool reveal=false){if(bookmark==null)return;bookmark.Restore(list,selected);if(!buildingPage||!IsHandleCreated)return;BeginInvoke((Action)delegate{if(IsDisposed||list.IsDisposed||list!=subscriptions&&list!=nodes)return;list.PerformLayout();bookmark.Restore(list,selected);if(reveal&&list.SelectedItems.Count>0)list.SelectedItems[0].EnsureVisible();});}
  SoftButton AvailableButton(string text,Action action,Func<bool> enabled,bool primary=false,int width=116){var button=Button(text,action,primary,width);availability[button]=enabled;return button;}
  void RefreshActions(){foreach(var pair in availability)if(!pair.Key.IsDisposed)pair.Key.Enabled=!busy&&pair.Value();if(focusNodeSearch&&!busy&&page==2&&search!=null&&!search.IsDisposed&&search.Enabled){search.Focus();search.SelectAll();focusNodeSearch=false;}if(nodeHint!=null&&!nodeHint.IsDisposed){nodeHint.Text=pendingGlobal?"Выберите выход в GLOBAL или в выбранной группе; после выбора действие продолжится.":!engine.Running?"Ядро не запущено. Подключите прокси на странице «Обзор» или запустите только ядро из трея.":groups==null||groups.Items.Count==0?(busy?"Получение групп…":"Нет доступных групп, обновите или проверьте подписку."):nodes.Items.Count==0?"Нет подходящих узлов. Нажмите Esc, чтобы сбросить поиск, или выберите другую группу.":"Узлов: "+nodes.Items.Count+" · Ctrl+F — поиск, Esc — сброс · глобальный режим использует выход GLOBAL";}}
  bool HasProfile(){return subscriptions!=null&&!subscriptions.IsDisposed&&subscriptions.SelectedItems.Count>0;}
  bool HasNode(){return engine.Running&&nodes!=null&&!nodes.IsDisposed&&nodes.SelectedItems.Count>0;}
  bool CanSelectNode(){if(!HasNode()||groups==null||groups.SelectedItem==null)return false;object raw;if(!proxyData.TryGetValue(groups.SelectedItem.ToString(),out raw))return false;var group=Dict(raw);string type=Str(group,"type");return (type=="Selector"||type=="URLTest"||type=="Fallback")&&(pendingGlobal||type!="Selector"||Str(group,"now")!=SelectedNode());}
  void Feedback(string message,bool error=false){noticeError=error;activity.ErrorState=error;activity.Invalidate();activity.Text=message;activity.Cursor=error?Cursors.Hand:Cursors.Default;hints.SetToolTip(activity,message+(error?"\nНажмите, чтобы открыть подробности в журнале.":""));}
  void RememberView(){if(page==1&&subscriptions!=null)profileBookmark=ViewBookmark.Capture(subscriptions);if(page==2&&groups!=null&&!groups.IsDisposed){rememberedProfile=engine.ActiveId??store.State.Active;rememberedGroup=groups.SelectedItem as string;rememberedSearch=search.Text;nodeBookmark=ViewBookmark.Capture(nodes);}}
  void RevealWindow(){if(!Visible||WindowState==FormWindowState.Minimized){Show();WindowState=FormWindowState.Normal;Activate();}}
  bool PrepareStart(){if(store.Active==null){ShowPage(1);RevealWindow();Feedback("Сначала добавьте подписку: вставьте ссылку или перетащите YAML-файл.");return false;}if(!File.Exists(engine.CoreFile)){ShowPage(4);RevealWindow();Feedback("Сначала выберите ядро mihomo и сохраните настройки.");return false;}return true;}
  void ToggleConnection(){if(preview||busy)return;if(engine.Proxy.Owned){Run(engine.Proxy.Restore,delegate{pendingConnect=false;Feedback("Системный прокси выключен, ядро продолжает работать и доступно устройствам LAN.");},"Отключение системного прокси…");return;}if(!engine.Running&&!PrepareStart())return;pendingConnect=true;Run(delegate{if(!engine.Running)engine.Start(store.Active);if(!engine.Proxy.Owned)engine.ToggleSystemProxy();},delegate{pendingConnect=false;Feedback("Системный прокси включён и доступен приложениям, учитывающим системный прокси.");},"Подключение прокси…");}
  protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(!busy&&keyData==(Keys.Control|Keys.F)){if(page!=2)ShowPage(2);focusNodeSearch=true;RefreshActions();return true;}if(!busy&&page==2&&keyData==Keys.Escape&&search!=null&&search.Text.Length>0){search.Clear();search.Focus();return true;}if(keyData==(Keys.Control|Keys.L)){ShowPage(3);return true;}if(!busy&&keyData==(Keys.Control|Keys.R)){if(page==2)RefreshNodes();else if(page==6)RefreshConnections();else return base.ProcessCmdKey(ref msg,keyData);return true;}return base.ProcessCmdKey(ref msg,keyData);}
  void ImportDroppedFile(string path){if(busy){Feedback("Выполняется операция, дождитесь её завершения перед импортом.");return;}int originPage=page;Subscription created=null;Run(delegate{if(new FileInfo(path).Length>8*1024*1024)throw new IOException("Файл больше 8 МиБ.");string yaml=File.ReadAllText(path);engine.Validate(engine.Build(yaml));created=new Subscription(){Name=Path.GetFileNameWithoutExtension(path),Updated=DateTime.UtcNow.ToString("o"),Usage="Локальная конфигурация"};Store.Atomic(store.ProfilePath(created),yaml);AddProfile(created);},delegate{if(page==originPage)ShowPage(1);FillProfiles(created.Id);Feedback("Импортировано: "+created.Name+", можно подключиться на странице «Обзор».");},"Проверка и импорт YAML…");}
  void InitExperience(){activity.Click+=delegate{if(noticeError&&!busy)ShowPage(3);};hints.SetToolTip(activity,"Состояние операций; нажмите на ошибку, чтобы открыть журнал.");AllowDrop=true;DragEnter+=delegate(object sender,DragEventArgs e){var files=e.Data.GetData(DataFormats.FileDrop) as string[];e.Effect=!busy&&files!=null&&files.Length==1&&(files[0].EndsWith(".yaml",StringComparison.OrdinalIgnoreCase)||files[0].EndsWith(".yml",StringComparison.OrdinalIgnoreCase))?DragDropEffects.Copy:DragDropEffects.None;};DragDrop+=delegate(object sender,DragEventArgs e){var files=e.Data.GetData(DataFormats.FileDrop) as string[];if(files!=null&&files.Length==1)ImportDroppedFile(files[0]);};}
 }
}
